// Task **Executional task** tracked in this agent's local state. The
// Control Plane delegates one operation (e.g. start a VM, scan a
// pool, perform an outgoing migration) and polls this endpoint
// until the task reaches a terminal status.
//
// Distinct from Control-Plane saga tasks (which live in the CP
// database and may orchestrate several agent-side tasks under
// the hood). The `task_id`s are unrelated across the two
// surfaces; clients receive the agent task id from the
// `AsyncTaskAccepted` body of the triggering call.
//
// Persisted in the agent's embedded local store so polling
// survives an agent restart for the duration of the task TTL.
type Task struct {
	Attempts  int       `json:"attempts"`
	CreatedAt time.Time `json:"created_at"`

	// Error Populated on failure. Same shape as the inner `error` of
	// the standard error envelope.
	Error *struct {
		// Code Stable machine-readable error code. Endpoint-specific codes
		// beyond this enum may be returned for narrow cases; clients
		// must accept unknown values gracefully.
		Code    *ErrorCode              `json:"code,omitempty"`
		Details *map[string]interface{} `json:"details,omitempty"`
		Message *string                 `json:"message,omitempty"`
	} `json:"error,omitempty"`
	FinishedAt  *time.Time         `json:"finished_at,omitempty"`
	ID          openapi_types.UUID `json:"id"`
	MaxAttempts int                `json:"max_attempts"`

	// Progress Progress percentage. `null` if the task type does not
	// report progress.
	Progress *int `json:"progress,omitempty"`

	// ResourceID Resource identifier — UUID for VMs / pools / migrations,
	// `(vm_uuid, name)`-style composite for snapshots, or
	// `(vm_uuid, device_order)` for disks / NICs. The exact
	// format depends on `resource_type`.
	ResourceID *string `json:"resource_id,omitempty"`

	// ResourceType The resource the task acts on, e.g. `vm`, `vm_disk`,
	// `storage_pool`, `vm_migration`.
	ResourceType string `json:"resource_type"`

	// Result Task-type-specific payload, populated on success. For
	// `vm.create` the agent returns `vm_id` (string uuid),
	// `image_sha256` (the resolved image content digest - the computed
	// digest for an unpinned image, the verified digest for a pinned one),
	// `virtual_size_bytes` (int64, the image's virtual size) and
	// `disk_size_bytes` (int64, the materialized root-disk size).
	Result    *map[string]interface{} `json:"result,omitempty"`
	StartedAt *time.Time              `json:"started_at,omitempty"`
	Status    TaskStatus              `json:"status"`

	// Type Task type identifier in `<resource>.<action>` form, e.g.
	// `vm.start`, `vm.create`, `storage_pool.scan`,
	// `vm_migration.outgoing`.
	Type string `json:"type"`
}

